import {
  boundedMessage,
  numberValue,
  packageSegment,
  record,
  records,
  requiredRecord,
  requiredString,
  sameBounds,
  stringValue,
  strings,
  uniqueStrings,
} from "./overlay-common.mjs";

export function prepareBinding(inputs) {
  const evidence = requiredRecord(inputs.source_evidence, "source_evidence");
  const draft = record(inputs.profile_draft);
  const markdown = typeof inputs.skill_markdown === "string" ? inputs.skill_markdown : "";
  const blockers = [];
  try {
    if (evidence.decision !== "ready") throw new Error("source evidence is not ready");
    if (draft.decision !== "ready") throw new Error("profile draft is not ready");
    enforceBounds(evidence.bounds, draft.bounds_applied);
    const profileDocument = requiredString(draft.profile_document, "profile_draft.profile_document");
    return {
      binding_candidate: {
        decision: "ready",
        source_evidence: evidence,
        rationale: requiredString(draft.rationale, "profile_draft.rationale"),
        profile_document: profileDocument,
        candidate_files: [
          { path: "SKILL.md", contents: markdown },
          { path: "run.yaml", contents: profileDocument },
        ],
        blockers: [],
      },
    };
  } catch (error) {
    blockers.push(boundedMessage(error));
    return {
      binding_candidate: {
        decision: "reject",
        source_evidence: evidence,
        rationale: stringValue(draft.rationale) || "The binding candidate failed deterministic validation.",
        blockers,
      },
    };
  }
}

export function assembleBinding(inputs) {
  const candidate = requiredRecord(inputs.binding_candidate, "binding_candidate");
  const validation = requiredRecord(inputs.skill_validation, "skill_validation");
  if (candidate.decision !== "ready") return rejectedDocuments(candidate, "binding candidate is not ready");
  if (validation.verdict !== "tested" || validation.harness?.status !== "passed") {
    return rejectedDocuments(candidate, "native skill validation or harness proof failed");
  }
  const evidence = requiredRecord(candidate.source_evidence, "source_evidence");
  const sourceEvidence = requiredRecord(evidence.source, "source_evidence.source");
  const inspection = requiredRecord(validation.inspect, "skill_validation.inspect");
  const skillName = packageSegment(inspection.name, "skill_validation.inspect.name");
  const description = stringValue(inspection.description) || "Upstream skill bound by Runx.";
  const source = { ...sourceEvidence, name: skillName, description };
  const owner = requiredString(evidence.registry.owner, "registry.owner");
  const bindingPath = `bindings/${owner}/${skillName}`;
  const skillId = `${owner}/${skillName}`;
  const harness = requiredRecord(validation.harness, "skill_validation.harness");
  const binding = {
    schema: "runx.registry_binding.v1",
    state: "harness_verified",
    skill: { id: skillId, name: skillName, description: requiredString(source.description, "source.description") },
    upstream: evidence.upstream,
    registry: {
      owner,
      trust_tier: evidence.registry.trust_tier,
      version: evidence.registry.version,
      install_command: `runx registry install ${skillId}@${evidence.registry.version}`,
      run_command: `runx skill ${skillId}@${evidence.registry.version}`,
      profile_path: `${bindingPath}/run.yaml`,
      materialized_package_is_registry_artifact: true,
    },
    harness: {
      status: "harness_verified",
      case_count: numberValue(harness.case_count),
      assertion_count: numberValue(harness.case_count),
      case_names: uniqueStrings(harness.case_names),
    },
    bounds: Object.keys(record(evidence.bounds)).length > 0 ? evidence.bounds : null,
    publication: evidence.publication,
    tags: uniqueStrings(evidence.tags),
  };
  return {
    binding_documents: {
      decision: "ready",
      binding_path: bindingPath,
      source,
      profile_document: requiredString(candidate.profile_document, "profile_document"),
      binding_document: `${JSON.stringify(binding, null, 2)}\n`,
      validation,
      rationale: candidate.rationale,
      blockers: [],
    },
  };
}

export function finalizeBinding(inputs) {
  const documents = record(inputs.binding_documents);
  if (documents.decision === "ready") {
    const profileDigest = requiredRecord(inputs.profile_digest, "profile_digest");
    const bindingDigest = requiredRecord(inputs.binding_digest, "binding_digest");
    return {
      binding_bundle: {
        decision: "ready",
        binding_path: documents.binding_path,
        source: documents.source,
        files: [
          fileEntry(`${documents.binding_path}/binding.json`, documents.binding_document, bindingDigest.digest),
          fileEntry(`${documents.binding_path}/run.yaml`, documents.profile_document, profileDigest.digest),
        ],
        validation: {
          status: "pass",
          inspect: documents.validation.inspect,
          harness: documents.validation.harness,
        },
        rationale: documents.rationale,
        blockers: [],
        success_checkpoint: {
          milestone: "binding_bundle_ready",
          description: "Exact native binding files passed profile inspection and isolated harness proof; repository write and publication remain separate.",
        },
      },
    };
  }
  const request = record(inputs.source_request);
  const evidence = record(inputs.source_evidence);
  const candidate = record(inputs.binding_candidate);
  const sourceEvidence = Object.keys(record(candidate.source_evidence)).length > 0 ? candidate.source_evidence : evidence;
  const blockers = [
    ...records(request.findings).map((finding) => stringValue(finding.message)).filter(Boolean),
    ...records(sourceEvidence.findings).map((finding) => stringValue(finding.message)).filter(Boolean),
    ...strings(candidate.blockers),
    ...strings(documents.blockers),
  ];
  return {
    binding_bundle: {
      decision: "reject",
      binding_path: stringValue(sourceEvidence.binding_path) || "",
      source: record(sourceEvidence.source),
      files: [],
      validation: { status: "hold" },
      rationale: stringValue(candidate.rationale) || "The binding candidate failed deterministic validation.",
      blockers: [...new Set(blockers.length > 0 ? blockers : ["The binding request is incomplete or invalid."])],
      success_checkpoint: { milestone: "binding_blocked", description: "No binding files were released." },
    },
  };
}

function enforceBounds(bounds, applied) {
  const declared = record(bounds);
  if (Object.keys(declared).length === 0) {
    if (Object.keys(record(applied)).length > 0) {
      throw new Error("profile draft applied bounds the caller did not supply");
    }
    return;
  }
  if (!sameBounds(declared, applied)) {
    throw new Error("profile draft did not apply the caller-supplied bounds exactly");
  }
}

function rejectedDocuments(candidate, reason) {
  return { binding_documents: { decision: "reject", blockers: [...strings(candidate.blockers), reason] } };
}

function fileEntry(path, contents, digest) {
  return { path, contents, sha256: requiredString(digest, `${path} digest`) };
}

export function record(value) {
  return isRecord(value) ? value : {};
}

export function requiredRecord(value, field) {
  const parsed = record(value);
  if (Object.keys(parsed).length === 0) throw new Error(`${field} must be a non-empty object`);
  return parsed;
}

export function requiredString(value, field) {
  const parsed = stringValue(value);
  if (!parsed) throw new Error(`${field} must be a non-empty string`);
  return parsed;
}

export function stringValue(value) {
  return typeof value === "string" && value.trim() ? value.trim() : null;
}

export function strings(value) {
  return Array.isArray(value) ? value.map(stringValue).filter(Boolean) : [];
}

export function uniqueStrings(value) {
  return [...new Set(strings(value))].sort();
}

export function records(value) {
  return Array.isArray(value) ? value.map(record) : [];
}

export function isRecord(value) {
  return value && typeof value === "object" && !Array.isArray(value);
}

export function packageSegment(value, field) {
  const parsed = requiredString(value, field);
  if (!/^[a-z0-9][a-z0-9-]*$/u.test(parsed)) throw new Error(`${field} must be a lowercase package segment`);
  return parsed;
}

export function enumValue(value, allowed, field) {
  if (!allowed.includes(value)) throw new Error(`${field} must be one of ${allowed.join(", ")}`);
  return value;
}

export function numberValue(value) {
  return Number.isFinite(value) ? Math.max(0, Math.trunc(value)) : 0;
}

export function boundedMessage(error) {
  return (error instanceof Error ? error.message : "Binding validation failed")
    .replace(/\s+/gu, " ")
    .trim()
    .slice(0, 300);
}

const BOUNDS_FIELDS = ["allowed_output_prefix", "max_acts"];

export function normalizedBounds(value) {
  if (value === undefined || value === null) return { bounds: null, errors: [] };
  const errors = [];
  if (!isRecord(value)) return { bounds: null, errors: ["bounds must be an object"] };
  const unknown = Object.keys(value).filter((key) => !BOUNDS_FIELDS.includes(key));
  if (unknown.length > 0) errors.push(`bounds contains unknown fields: ${unknown.sort().join(", ")}`);
  const bounds = {};
  if (value.allowed_output_prefix !== undefined) {
    const prefix = normalizedPrefix(value.allowed_output_prefix, errors);
    if (prefix) bounds.allowed_output_prefix = prefix;
  }
  if (value.max_acts !== undefined) {
    if (!Number.isInteger(value.max_acts) || value.max_acts < 1 || value.max_acts > 10000) {
      errors.push("bounds.max_acts must be an integer between 1 and 10000");
    } else {
      bounds.max_acts = value.max_acts;
    }
  }
  if (errors.length === 0 && Object.keys(bounds).length === 0) {
    errors.push("bounds must declare allowed_output_prefix or max_acts");
  }
  return errors.length === 0 ? { bounds, errors } : { bounds: null, errors };
}

export function sameBounds(left, right) {
  const a = record(left);
  const b = record(right);
  if (Object.keys(b).some((key) => !BOUNDS_FIELDS.includes(key))) return false;
  return BOUNDS_FIELDS.every((field) => a[field] === b[field]);
}

function normalizedPrefix(value, errors) {
  const raw = stringValue(value);
  if (!raw || raw.length > 4000) {
    errors.push("bounds.allowed_output_prefix must be a non-empty path of at most 4000 characters");
    return null;
  }
  const absolute = raw.startsWith("/");
  const parts = raw.replaceAll("\\", "/").split("/");
  if (parts.some((part) => part === "..")) {
    errors.push("bounds.allowed_output_prefix must not contain parent traversal");
    return null;
  }
  const normalized = parts.filter((part) => part && part !== ".").join("/");
  if (!normalized) {
    errors.push("bounds.allowed_output_prefix must name a directory prefix");
    return null;
  }
  return absolute ? `/${normalized}` : normalized;
}

import {
  boundedMessage,
  normalizedBounds,
  numberValue,
  record,
  records,
  requiredRecord,
  requiredString,
  stringValue,
  uniqueStrings,
} from "./overlay-common.mjs";

export function planSource(inputs) {
  const findings = [];
  const rawPath = stringValue(inputs.skill_path);
  const { bounds, errors: boundsErrors } = normalizedBounds(inputs.bounds);
  for (const message of boundsErrors) {
    findings.push({ code: "bounds.invalid", path: "bounds", message });
  }
  let base = "workspace";
  let path = "";
  const label = rawPath || "";
  try {
    if (!rawPath) throw new Error("A pinned local SKILL.md path is required.");
    if (rawPath.startsWith("skill://")) {
      base = "skill";
      path = normalizeRelative(rawPath.slice("skill://".length));
    } else {
      path = normalizeRelative(rawPath);
    }
    if (!path.endsWith("SKILL.md")) throw new Error("skill_path must name a SKILL.md file");
  } catch (error) {
    findings.push({ code: "source.invalid_path", path: "skill_path", message: boundedMessage(error) });
  }
  return {
    source_request: {
      decision: findings.length === 0 ? "read" : "reject",
      base,
      path,
      label,
      upstream: record(inputs.upstream),
      registry: record(inputs.registry),
      bounds,
      tags: uniqueStrings(inputs.tags),
      publication: Object.keys(record(inputs.publication)).length > 0 ? inputs.publication : { status: "not_published" },
      findings,
    },
  };
}

export function inspectSource(inputs) {
  const request = requiredRecord(inputs.source_request, "source_request");
  const file = requiredRecord(inputs.file_read, "file_read");
  const blobDigest = requiredRecord(inputs.git_blob_digest, "git_blob_digest");
  const findings = [...records(request.findings)];
  if (file.truncated === true) {
    findings.push({ code: "source.too_large", path: "skill_path", message: "SKILL.md exceeds the bounded read limit." });
  }
  const upstream = requiredRecord(request.upstream, "upstream");
  const registry = requiredRecord(request.registry, "registry");
  const observedBlobSha = requiredString(blobDigest.digest, "git_blob_digest.digest");
  validateUpstream(upstream, observedBlobSha, findings);
  validateRegistry(registry, findings);
  return {
    source_evidence: {
      decision: findings.length === 0 ? "ready" : "reject",
      findings,
      source: {
        path: request.label,
        bytes: numberValue(blobDigest.bytes),
        sha256: requiredString(file.content_digest, "file_read.content_digest"),
        git_blob_sha: observedBlobSha,
      },
      upstream,
      registry,
      bounds: request.bounds ?? null,
      tags: uniqueStrings(request.tags),
      publication: request.publication,
    },
  };
}

function validateUpstream(value, observedBlobSha, findings) {
  if (value.host !== "github.com") {
    reject(findings, "upstream.unsupported_host", "upstream.host", "Native upstream bindings currently require github.com provenance.");
  }
  const owner = safeSegment(value.owner, "upstream.owner", findings);
  const repo = safeSegment(value.repo, "upstream.repo", findings);
  if (value.path !== "SKILL.md") {
    reject(findings, "upstream.invalid_path", "upstream.path", "The upstream source-of-truth path must be SKILL.md.");
  }
  const commit = hex(value.commit, 40, "upstream.commit", findings);
  const blobSha = hex(value.blob_sha, 40, "upstream.blob_sha", findings);
  if (blobSha && blobSha !== observedBlobSha) {
    reject(findings, "upstream.blob_mismatch", "upstream.blob_sha", "The local SKILL.md does not match the pinned upstream Git blob.");
  }
  if (value.source_of_truth !== true) {
    reject(findings, "upstream.not_source_of_truth", "upstream.source_of_truth", "The binding requires an upstream source-of-truth assertion.");
  }
  pinnedUrl(value.html_url, [owner, repo, commit, "SKILL.md"], "upstream.html_url", findings);
  pinnedUrl(value.raw_url, [owner, repo, commit, "SKILL.md"], "upstream.raw_url", findings);
}

function validateRegistry(value, findings) {
  safeSegment(value.owner, "registry.owner", findings);
  if (!["community", "verified", "first_party"].includes(value.trust_tier)) {
    reject(findings, "registry.invalid_trust_tier", "registry.trust_tier", "Registry trust tier must be community, verified, or first_party.");
  }
  if (!/^[A-Za-z0-9][A-Za-z0-9._-]*$/u.test(stringValue(value.version) || "")) {
    reject(findings, "registry.invalid_version", "registry.version", "Registry version must be an immutable package segment.");
  }
}

function normalizeRelative(value) {
  const raw = String(value);
  const parts = raw.replaceAll("\\", "/").split("/");
  if (parts.some((part) => part === "..") || raw.startsWith("/")) {
    throw new Error("skill_path must stay inside its source root");
  }
  const normalized = parts.filter((part) => part && part !== ".").join("/");
  if (!normalized) throw new Error("skill_path must name a file");
  return normalized;
}

function safeSegment(value, field, findings) {
  const parsed = stringValue(value);
  if (!parsed || !/^[a-z0-9][a-z0-9-]*$/u.test(parsed)) {
    reject(findings, "binding.invalid_segment", field, `${field} must be a lowercase package segment.`);
    return "invalid";
  }
  return parsed;
}

function hex(value, length, field, findings) {
  const parsed = stringValue(value);
  if (!parsed || !new RegExp(`^[a-f0-9]{${length}}$`, "iu").test(parsed)) {
    reject(findings, "binding.invalid_digest", field, `${field} must be a ${length}-character hex digest.`);
    return null;
  }
  return parsed.toLowerCase();
}

function pinnedUrl(value, parts, field, findings) {
  const parsed = stringValue(value);
  if (!parsed || parts.some((part) => part && !parsed.includes(part))) {
    reject(findings, "upstream.unpinned_url", field, "Pinned upstream URLs must include owner, repo, commit, and SKILL.md path.");
  }
}

function reject(findings, code, path, message) {
  findings.push({ code, path, message });
}

